@startuml

class City {
  + Name : string
}

class H2SLocation {
  + City : string
}

class Resident {
  + Name : string
  + StreetAddress : string
  + PhoneNumber : string
  + Email : string
}

class PickupRequest {
  + Description : string
  + RequestedDate : date
  + RequestedTime : time
}

class Item {
  + Description : string
  + Weight : float
  + Dimensions : string
}

class Vehicle {
  + LicensePlate : string
  + StorageCapacity : float
}

class VolunteerDriver {
  + Name : string
  + AvailableDays : string[]
}

class PickupRoute {
  + Date : date
}

class DistributionCenter {
  + Address : string
}

class Article {
  + RFIDTag : string
  + Category : string
}

class FoodItem {
  + Description : string
}

class H2SEmployee {
  + Name : string
}

class Client {
  + Name : string
  + HomeAddress : string
  + NeededCategories : string[]
}

class Delivery {
  + Date : date
}

City "1" -- "1..*" H2SLocation
H2SLocation "1" -- "1" DistributionCenter
Resident "1" -- "0..*" PickupRequest
PickupRequest "1" -- "1..*" Item
Vehicle "1" -- "0..*" PickupRoute
VolunteerDriver "1" -- "0..*" PickupRoute
PickupRoute "1" -- "1..*" PickupRequest
PickupRequest "1" -- "1" Vehicle
Item "1" -- "0..1" Article
Item "1" -- "0..1" FoodItem
DistributionCenter "1" -- "*" Article
DistributionCenter "1" -- "*" FoodItem
H2SEmployee "1" -- "*" Article
Client "1" -- "0..*" Delivery
Delivery "1" -- "1" Article
VolunteerDriver "1" -- "0..*" Delivery

@enduml

